"""Compare a diffrax source tree against the pristine pip diffrax across valid
stochastic configurations: controls, levy areas, solvers, intervals, models.

Usage: python battery.py <source_dir_or_pip>  -> writes /tmp/battery_<tag>.pkl
"""
import pickle
import sys

import jax

jax.config.update("jax_enable_x64", True)

mode = sys.argv[1]
if mode != "pip":
    for m in list(sys.modules):
        if m == "diffrax" or m.startswith("diffrax."):
            del sys.modules[m]
    sys.path.insert(0, mode)

import diffrax as dfx  # noqa: E402
import jax.numpy as jnp  # noqa: E402
import jax.random as jr  # noqa: E402
import numpy as np  # noqa: E402

print("diffrax:", dfx.__file__)

levy_areas = {
    "bm": dfx.BrownianIncrement,
    "st": dfx.SpaceTimeLevyArea,
    "stt": dfx.SpaceTimeTimeLevyArea,
}

solvers = {
    "sea": dfx.SEA(),
    "slowrk": dfx.SlowRK(),
    "gshark": dfx.GeneralShARK(),
    "spark": dfx.SPaRK(),
    "eulerheun": dfx.EulerHeun(),
}

intervals = {
    "fwd01": (0.0, 1.0),
    "rev10": (1.0, 0.0),
    "fwd_shift": (-0.5, 0.75),
    "rev_shift": (0.75, -0.5),
}


def make_models():
    def drift_scalar(t, y, args):
        return jnp.sin(y)

    def diffusion_scalar(t, y, args):
        return args * jnp.ones_like(y)

    def drift_vec(t, y, args):
        return jnp.stack([jnp.sin(y[1]), -jnp.sin(y[0])])

    def diffusion_vec(t, y, args):
        return args * jnp.array([[1.0, 0.0], [0.3, 1.0]])

    return {
        "scalar": (drift_scalar, diffusion_scalar, jnp.array(1.0), ()),
        "vector": (drift_vec, diffusion_vec, jnp.array([1.0, -0.5]), (2,)),
    }


def run_case(ctrl_kind, levy_name, solver_name, int_name, model_name, seed):
    drift, diffusion, y0, wshape = make_models()[model_name]
    levy = levy_areas[levy_name]
    solver = solvers[solver_name]
    t0, t1 = intervals[int_name]
    step = jnp.copysign(0.04, t1 - t0)
    shape = jax.ShapeDtypeStruct(wshape, jnp.float64)
    ts = jnp.linspace(t0, t1, 9)

    def solve_one(key):
        if ctrl_kind == "vbt":
            control = dfx.VirtualBrownianTree(
                t0=min(t0, t1), t1=max(t0, t1), tol=1e-3, shape=shape, key=key,
                levy_area=levy,
            )
        else:
            control = dfx.UnsafeBrownianPath(shape=shape, key=key, levy_area=levy)
        terms = dfx.MultiTerm(
            dfx.ODETerm(drift), dfx.ControlTerm(diffusion, control)
        )
        sol = dfx.diffeqsolve(
            terms, solver, t0=t0, t1=t1, dt0=step, y0=y0,
            saveat=dfx.SaveAt(ts=ts),
            stepsize_controller=dfx.ConstantStepSize(),
            max_steps=2**16,
            args=jnp.array(0.7),
        )
        return sol.ys

    keys = jr.split(jr.key(seed), 4)
    return np.asarray(jax.jit(jax.vmap(solve_one))(keys))


results = {}
seed = 12345
for ctrl_kind in ("vbt", "unsafe"):
    for levy_name in levy_areas:
        for solver_name in solvers:
            # only pair levy areas with solvers that need/support them is not
            # required; diffrax downgrades levy areas gracefully for solvers
            # that don't use them.
            for int_name in intervals:
                for model_name in ("scalar", "vector"):
                    tag = f"{ctrl_kind}/{levy_name}/{solver_name}/{int_name}/{model_name}"
                    try:
                        arr = run_case(ctrl_kind, levy_name, solver_name, int_name, model_name, seed)
                        results[tag] = arr
                        ok = np.isfinite(arr).all()
                    except Exception as exc:  # noqa: BLE001
                        results[tag] = ("ERR", type(exc).__name__, str(exc)[:120])
                        ok = None
                    print(tag, "->", "fin" if ok else results[tag], flush=True)

out = "/tmp/battery_pip.pkl" if mode == "pip" else "/tmp/battery_src.pkl"
with open(out, "wb") as f:
    pickle.dump(results, f)
print("wrote", out)

"""Focused battery: UnsafeBrownianPath controls with ForwardMode adjoint,
so UnsafeBrownianPath.evaluate (the repaired code path) is exercised.

Usage: python battery_ubp.py <source_dir_or_pip>
"""
import pickle
import sys

import jax

jax.config.update("jax_enable_x64", True)

mode = sys.argv[1]
if mode != "pip":
    for m in list(sys.modules):
        if m == "diffrax" or m.startswith("diffrax."):
            del sys.modules[m]
    sys.path.insert(0, mode)

import diffrax as dfx  # noqa: E402
import jax.numpy as jnp  # noqa: E402
import jax.random as jr  # noqa: E402
import numpy as np  # noqa: E402

print("diffrax:", dfx.__file__)

levy_areas = {
    "bm": dfx.BrownianIncrement,
    "st": dfx.SpaceTimeLevyArea,
    "stt": dfx.SpaceTimeTimeLevyArea,
}
solvers = {
    "sea": dfx.SEA(),
    "slowrk": dfx.SlowRK(),
    "gshark": dfx.GeneralShARK(),
    "spark": dfx.SPaRK(),
    "eulerheun": dfx.EulerHeun(),
}
intervals = {
    "fwd01": (0.0, 1.0),
    "rev10": (1.0, 0.0),
    "fwd_shift": (-0.5, 0.75),
    "rev_shift": (0.75, -0.5),
}


def make_models():
    def drift_scalar(t, y, args):
        return jnp.sin(y)

    def diffusion_scalar(t, y, args):
        return args * jnp.ones_like(y)

    def drift_vec(t, y, args):
        return jnp.stack([jnp.sin(y[1]), -jnp.sin(y[0])])

    def diffusion_vec(t, y, args):
        return args * jnp.array([[1.0, 0.0], [0.3, 1.0]])

    return {
        "scalar": (drift_scalar, diffusion_scalar, jnp.array(1.0), ()),
        "vector": (drift_vec, diffusion_vec, jnp.array([1.0, -0.5]), (2,)),
    }


def run_case(levy_name, solver_name, int_name, model_name, seed):
    drift, diffusion, y0, wshape = make_models()[model_name]
    levy = levy_areas[levy_name]
    solver = solvers[solver_name]
    t0, t1 = intervals[int_name]
    step = jnp.copysign(0.04, t1 - t0)
    shape = jax.ShapeDtypeStruct(wshape, jnp.float64)
    ts = jnp.linspace(t0, t1, 9)

    def solve_one(key):
        control = dfx.UnsafeBrownianPath(shape=shape, key=key, levy_area=levy)
        terms = dfx.MultiTerm(dfx.ODETerm(drift), dfx.ControlTerm(diffusion, control))
        sol = dfx.diffeqsolve(
            terms, solver, t0=t0, t1=t1, dt0=step, y0=y0,
            saveat=dfx.SaveAt(ts=ts),
            stepsize_controller=dfx.ConstantStepSize(),
            max_steps=2**16,
            args=jnp.array(0.7),
            adjoint=dfx.ForwardMode(),
        )
        return sol.ys

    keys = jr.split(jr.key(seed), 4)
    return np.asarray(jax.jit(jax.vmap(solve_one))(keys))


results = {}
seed = 777
for levy_name in levy_areas:
    for solver_name in solvers:
        for int_name in intervals:
            for model_name in ("scalar", "vector"):
                tag = f"unsafe/{levy_name}/{solver_name}/{int_name}/{model_name}"
                try:
                    arr = run_case(levy_name, solver_name, int_name, model_name, seed)
                    results[tag] = arr
                except Exception as exc:  # noqa: BLE001
                    results[tag] = ("ERR", type(exc).__name__, str(exc)[:120])
                print(tag, "->", "fin" if not isinstance(results[tag], tuple) else results[tag][:2], flush=True)

out = "/tmp/ubp_pip.pkl" if mode == "pip" else "/tmp/ubp_src.pkl"
with open(out, "wb") as f:
    pickle.dump(results, f)
print("wrote", out)
